const D = { energy: .6, scale: 1, density: .55, speed: 1, haze: .55, hue: 24, x: .5, y: .46, style: 'dusk', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Badlands at dusk. Five ranks of eroded buttes stand into their own haze; the beds run
// dead level THROUGH every rank at the same elevation, because they are the same beds — that
// is what makes it read as geology and not as scenery. Caprock holds flat tops, the soft
// beds beneath batter back into talus, and vertical fluting drains every face.
// A landscape is a still — so the camera never stops: the ranks dolly at incommensurate
// rates (new buttes are born at the frame edge for ever) and the low sun walks the faces,
// swapping lit for shadow across the whole frame. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
function hsh(ix,iy){ let h=(Math.imul(ix,374761393)+Math.imul(iy,668265263)+Math.imul(sd,1442695041))|0;
  h=Math.imul(h^(h>>>13),1274126177)|0; return ((h^(h>>>16))>>>0)/4294967295; }   // >>> : a >> fold caps the hash at 0.5
function fr(i){ return hsh((i*7+13)|0, (i*31+5)|0); }
function vn(x,y){ const ix=Math.floor(x), iy=Math.floor(y), fx=x-ix, fy=y-iy;
  const wx=fx*fx*(3-2*fx), wy=fy*fy*(3-2*fy);
  const a=hsh(ix,iy), b=hsh(ix+1,iy), c=hsh(ix,iy+1), d=hsh(ix+1,iy+1);
  return a+(b-a)*wx+(c-a)*wy+(a-b-c+d)*wx*wy; }
function fbm(x,y){ return .55*vn(x,y)+.28*vn(x*2.03+5.1,y*2.03-3.3)+.17*vn(x*4.07-2.7,y*4.07+7.9); }
function hsv(h,s,v){ h=(((h%360)+360)%360)/60; const c=v*s, xx=c*(1-Math.abs(h%2-1)), m=v-c;
  let r,g2,b2;
  if(h<1){r=c;g2=xx;b2=0}else if(h<2){r=xx;g2=c;b2=0}else if(h<3){r=0;g2=c;b2=xx}
  else if(h<4){r=0;g2=xx;b2=c}else if(h<5){r=xx;g2=0;b2=c}else{r=c;g2=0;b2=xx}
  return [(r+m)*255,(g2+m)*255,(b2+m)*255]; }

const sty = P.style, en = cl(P.energy,0,1), hz = cl(P.haze,0,1);
const Hh = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', ink = sty==='ink', sil = sty==='silhouette', thm = sty==='thermal';

// ---- palette ----
let skyT, skyH, hazeC, sunC;
if (ink)      { skyT=[Hh+150,4,90];  skyH=[Hh+150,3,96]; hazeC=[Hh+150,3,92]; sunC=[Hh+150,5,60]; }
else if (bp)  { skyT=[214,76,12];    skyH=[204,52,28];   hazeC=[201,44,34];   sunC=[188,50,96]; }
else if (thm) { skyT=[250,80,10];    skyH=[292,60,32];   hazeC=[312,48,40];   sunC=[44,88,99]; }
else if (sil) { skyT=[Hh+6,64,26];   skyH=[Hh+22,52,82]; hazeC=[Hh+18,40,60]; sunC=[Hh+30,26,99]; }
else          { skyT=[Hh+238,52,17]; skyH=[Hh+4,54,60];  hazeC=[Hh+12,34,50]; sunC=[Hh+8,44,98]; }

// ---- strata: ONE bed stack, shared by every rank, so the beds line up across the frame ----
if (S.seedUsed !== P.seed || !S.lut || S.lutSty !== sty){
  S.seedUsed = P.seed; S.lutSty = sty;
  const N2 = 256, lut = new Float32Array(N2*4);
  // build ~18 beds of varying thickness; a few are resistant caprock (hard)
  const beds = []; let e = 0, bi = 0;
  while (e < 1.0 && bi < 40){
    const th = .018 + fr(bi*3+1)*.085;
    const q = fr(bi*3+2), hard = fr(bi*3+3) > .72 ? 1 : 0;
    beds.push({ y0:e, y1:Math.min(1,e+th), q:q, hard:hard });
    e += th; bi++;
  }
  for (let i=0;i<N2;i++){
    const y = i/N2;
    let b = beds[beds.length-1];
    for (let k=0;k<beds.length;k++) if (y >= beds[k].y0 && y < beds[k].y1){ b = beds[k]; break; }
    const q = b.q;
    let h2,s2,v2;
    if (ink)      { h2 = Hh+150; s2 = 3+q*5;  v2 = 30 + q*40 + b.hard*10; }
    else if (bp)  { h2 = 196+q*16; s2 = 38+q*28; v2 = 26 + q*34 + b.hard*20; }
    else if (thm) { h2 = 268 - q*230; s2 = 60+q*30; v2 = 22 + q*62; }
    else if (sil) { h2 = Hh+200; s2 = 24; v2 = 6 + q*5; }
    else {
      // ochre / rust / bone / violet-grey beds — the classic Chinle/Brule stack
      const pick = q;
      if (pick < .30)      { h2 = Hh-8+q*18;  s2 = 54+q*30; v2 = 40+q*22; }   // rust
      else if (pick < .55) { h2 = Hh+14;      s2 = 34+q*16; v2 = 58+q*20; }   // ochre
      else if (pick < .78) { h2 = Hh+26;      s2 = 12+q*10; v2 = 66+q*18; }   // bone / ash
      else                 { h2 = Hh+230;     s2 = 16+q*12; v2 = 36+q*16; }   // violet-grey
      v2 += b.hard*8; s2 -= b.hard*6;
    }
    const c = hsv(h2, cl(s2,0,100)/100, cl(v2,0,100)/100);
    lut[i*4] = c[0]; lut[i*4+1] = c[1]; lut[i*4+2] = c[2]; lut[i*4+3] = b.hard;
  }
  S.lut = lut;
}
const LUT = S.lut;

const hzn = cl(P.y,.22,.72), hy = hzn*height;
const sc = cl(P.scale,.5,2.2);

// ---- perpetual dolly: monotonic, guarded against a t0 reset ----
if (S.pan == null) S.pan = 0;
if (S.lt == null || K.t < S.lt) S.lt = K.t;
const dt = cl(K.t - S.lt, 0, .1); S.lt = K.t;
S.pan += dt * P.speed * (.020 + .022*K.intensity) * (.85 + .15*Math.sin(tt*.041));
const pan = S.pan;
// the low sun walks the faces on two incommensurate rates — this alone re-lights the whole
// frame over 8s even if the camera were parked
const sunAz = .34*Math.sin(tt*.0273) + .16*Math.sin(tt*.0631+1.7);
const sunX = cl(P.x + sunAz*.5, -.2, 1.2);

const BW = 208, BH = Math.max(64, Math.round(BW*height/width));
if (!S.g || S.bk !== BW+'x'+BH){ if(S.g){ try{S.g.remove();}catch(e){} }
  S.g = createGraphics(BW,BH); S.g.pixelDensity(1); S.bk = BW+'x'+BH; }
const g = S.g; g.loadPixels(); const px = g.pixels;

const cT = hsv(skyT[0], skyT[1]/100, skyT[2]/100);
const cHo = hsv(skyH[0], skyH[1]/100, skyH[2]/100);
const cHz = hsv(hazeC[0], hazeC[1]/100, hazeC[2]/100);
const cSu = hsv(sunC[0], sunC[1]/100, sunC[2]/100);

// ---- ranks: far (0) -> near (NR-1). Precompute the skyline per column, once per frame. ----
const NR = 5;
const RK = [];
for (let i=0;i<NR;i++){
  const dep = 1 - i/(NR-1);                       // 1 far, 0 near
  RK.push({
    dep: dep,
    base: hy + (1-dep)*(height-hy)*1.02 + height*.004,
    hgt: height*(.045 + Math.pow(1-dep,1.7)*.58)*sc,
    span: 2.2 + dep*13.0,                         // world x per frame width: far ranks span more
    rate: .18 + Math.pow(1-dep,1.5)*3.2,          // parallax: near ranks slide faster
    ph: i*37.1
  });
}
// a slow, per-rank breathing offset on an incommensurate rate so ranks never re-align
for (let i=0;i<NR;i++){
  RK[i].wob = Math.sin(tt*(.017+i*.0071)+i*2.1)*.10;
  // slow vertical drift of the camera. The beds are elevation-indexed, so this is the ONLY
  // thing that can slide them on screen; lateral dolly alone leaves the dominant colour
  // signal frozen. Parallax-correct: near ranks rise and fall further than far ones.
  RK[i].bob = (Math.sin(tt*(.0233+i*.0091)+i*1.7)*.62 + Math.sin(tt*(.0571+i*.0043)+i*.9)*.38)
              * height*.016*(.25 + (1-RK[i].dep)*1.9);
  RK[i].base += RK[i].bob;
}

function skyline(xw, R){
  const f = fbm(xw*.55 + R.ph, R.ph*.31);
  const f2 = fbm(xw*1.9 - R.ph*.7, R.ph*.11+7.3);
  let h2 = cl(f*1.35-.16, 0, 1);
  // benches: quantize to caprock levels, then a short batter — this is what makes MESAS
  const nb = 5;
  const qq = h2*nb, flq = Math.floor(qq), fq = qq-flq;
  h2 = (flq + Math.min(1, fq*3.6)*.92)/nb;
  h2 += (f2-.5)*.11;
  return cl(h2, 0, 1.05);
}
const SKY = [], DHD = [];
for (let i=0;i<NR;i++){
  const R = RK[i];
  const a = new Float32Array(BW+1), d2 = new Float32Array(BW+1);
  for (let c=0;c<=BW;c++){
    const nx = c/BW;
    const xw = (nx-.5)*R.span + pan*R.rate + R.wob;
    a[c] = skyline(xw, R);
  }
  for (let c=0;c<=BW;c++){
    const c0 = Math.max(0,c-1), c1 = Math.min(BW,c+1);
    d2[c] = (a[c1]-a[c0])*BW/ (R.span*.5+1);      // slope, for the lambert term
  }
  SKY.push(a); DHD.push(d2);
}

const dustT = tt*.09;
const sunB = (.55+en*.75)*(.86 + .10*Math.sin(tt*.053) + .06*Math.sin(tt*.131+1.1) + K.swell*.08 + A.lowmid*.10);

for (let j=0;j<BH;j++){
  const ny = (j+.5)/BH;
  for (let i=0;i<BW;i++){
    const nx = (i+.5)/BW;
    let r,g2,b2, hit = -1, elev = 0, lit = .5, flute = .5, dep = 1;
    // --- occlusion walk: nearest rank whose mass covers this pixel wins ---
    for (let k=NR-1;k>=0;k--){
      const R = RK[k];
      const sy = (R.base - SKY[k][i]*R.hgt)/height;
      if (ny >= sy){
        hit = k; dep = R.dep;
        elev = cl((R.base/height - ny)/(R.hgt/height), 0, 1);
        const slope = DHD[k][i];
        const xw = (nx-.5)*R.span + pan*R.rate + R.wob;
        // lambert against the walking sun. A smooth azimuth term, not a hard left/right flip:
        // as the sun tracks, the terminator sweeps the whole frame and faces trade lit for
        // shadow — this re-lights everything over 8s even with the camera parked.
        const sdir = Math.tanh((sunX-nx)*3.2);
        lit = cl(.44 + slope*sdir*(1.8+en*1.5)*.55 + sdir*.13, 0, 1);
        lit = lit*(.55+ .45*Math.pow(1-elev,.4));                 // tops catch more sky light
        // Cloud shadows crawling the faces. THE motion floor for this piece: the beds are
        // indexed by ELEVATION, so a horizontal dolly cannot move them — the dominant colour
        // signal is pan-invariant and the frame reads STATIC without this. Broad, high
        // contrast, drifting on rates incommensurate with the dolly.
        const csh = cl((fbm(xw*.40 + tt*.058, elev*.55 + k*2.1 + tt*.021)-.42)*2.4, 0, 1);
        lit *= 1 - csh*(.44+en*.20);
        // vertical fluting: rills draining every face — the texture that says "eroded"
        flute = fbm(xw*22 + k*3.1, elev*2.2);
        break;
      }
    }
    if (hit < 0){
      // ---- sky: dusk. Mid-key, NOT a blown pale wash (rice_terraces landed 0.59 and reads
      // washed) — deep at the zenith, warm only in a band at the horizon. ----
      const sv = Math.pow(cl(ny/hzn,0,1), 1.7);
      r = cT[0]+(cHo[0]-cT[0])*sv; g2 = cT[1]+(cHo[1]-cT[1])*sv; b2 = cT[2]+(cHo[2]-cT[2])*sv;
      // the sun's glow sitting on the horizon, tracking with sunX
      const dsx = (nx-sunX)*1.6, dsy = (ny-hzn*.985)*3.4;
      const dsun = Math.sqrt(dsx*dsx+dsy*dsy);
      const gl = Math.exp(-dsun*2.6)*(.30+en*.85)*sunB;
      r += cSu[0]*gl*.55; g2 += cSu[1]*gl*.55; b2 += cSu[2]*gl*.55;
      // thin cloud bars, drifting on their own rate — a broad live element in the sky half
      const cb = fbm(nx*2.6 + tt*.045, ny*9.5 + tt*.017);
      const bar = cl((cb-.48)*3.0,0,1) * cl(1-ny/hzn*.5,0,1) * (.30+en*.5);
      r += (cSu[0]*.75-r)*bar*.36*sunB; g2 += (cSu[1]*.75-g2)*bar*.36*sunB; b2 += (cSu[2]*.75-b2)*bar*.36*sunB;
    } else {
      // ---- rock: the shared bed stack, sampled at this pixel's elevation ----
      const li = cl(Math.floor(elev*255), 0, 255)|0;
      let rr = LUT[li*4], gg = LUT[li*4+1], bb = LUT[li*4+2];
      const hard = LUT[li*4+3];
      // fluting darkens the rills; caprock beds stand proud and catch a hard edge
      const fl = (flute-.5)*(.30+ (1-hard)*.34);
      const sh = (.44 + lit*.86) * (1 + fl) * (1 - (1-hard)*.05);
      rr *= sh; gg *= sh; bb *= sh;
      // talus apron: soft beds shed scree that fans out and buries the base
      const tal = cl(1 - elev/.20, 0, 1)*Math.pow(cl(1-elev/.20,0,1),.6);
      const tc = LUT[Math.floor(.14*255)*4];
      rr += (tc*.9-rr)*tal*.45; gg += (LUT[Math.floor(.14*255)*4+1]*.9-gg)*tal*.45;
      bb += (LUT[Math.floor(.14*255)*4+2]*.9-bb)*tal*.45;
      // aerial perspective: each rank sits behind more air than the one in front
      const ha = cl(dep*dep*(.34+hz*1.0), 0, .93);
      r = rr+(cHz[0]-rr)*ha; g2 = gg+(cHz[1]-gg)*ha; b2 = bb+(cHz[2]-bb)*ha;
    }
    // ---- dust hanging in the troughs between the ranks: a broad, drifting, low-alpha veil
    // that crosses the whole frame. Carries motion where the rock is momentarily still. ----
    const dv = fbm(nx*2.3 + dustT*.5, ny*3.1 - dustT*.16);
    const dust = cl((dv-.40)*1.7,0,1) * cl((ny-hzn*.90)*3.2,0,1) * cl(1-(ny-hzn)*1.5,0,1) * hz*(.30+en*.34);
    r += (cHz[0]-r)*dust*.55; g2 += (cHz[1]-g2)*dust*.55; b2 += (cHz[2]-b2)*dust*.55;

    const o = 4*(j*BW+i);
    px[o]=cl(r,0,255); px[o+1]=cl(g2,0,255); px[o+2]=cl(b2,0,255); px[o+3]=255;
  }
}
g.updatePixels();
push();
if (P.alpha<100) tint(0,0,100,P.alpha);
image(g,0,0,width,height);
pop();

const AL = P.alpha/100;
const dens = cl(P.density,0,1);

// ---- blown dust veils drifting across the ranks ----
push();
noStroke();
const NV = Math.round(4 + dens*7);
for (let i=0;i<NV;i++){
  const f1 = fr(i*5+601), f2 = fr(i*5+602), f3 = fr(i*5+603);
  const vx = ((f1 + tt*(.0055+f2*.013)*P.speed) % 1.5 - .25)*width;
  const vy = hy + (f2-.25)*height*.30;
  fill(hazeC[0], hazeC[1]*(.6+f3*.5), hazeC[2]*(.85+f3*.4), (5+hz*10)*AL);
  ellipse(vx, vy + Math.sin(tt*(.07+f1*.15)+f2*6)*height*.010,
          width*(.26+f1*.46), height*(.016+f3*.055));
}
pop();

// ---- ravens riding the thermals off the near rank: slow, and the only living thing ----
push();
noStroke();
const NB = Math.round(dens*6);
for (let i=0;i<NB;i++){
  const f1 = fr(i*7+701), f2 = fr(i*7+702), f3 = fr(i*7+703);
  // a lazy, non-closing lissajous — never returns to the same point
  const ax = .5 + .34*Math.sin(tt*(.031+f1*.05)+f1*6.28) + .13*Math.sin(tt*(.079+f2*.04)+f2*6.28);
  const ay = .30 + .16*Math.sin(tt*(.047+f3*.06)+f3*6.28) + .05*Math.sin(tt*(.113+f1*.03));
  const bs = u*.0055*(.5+f2)*sc;
  const flap = Math.sin(tt*(2.6+f1*1.7)+f2*6.28)*.55;
  fill(skyT[0], skyT[1]*.5, skyT[2]*(.5+f1*.4), 60*AL);
  beginShape();
  vertex(ax*width-bs, ay*hy - bs*flap*.8); vertex(ax*width, ay*hy);
  vertex(ax*width+bs, ay*hy - bs*flap*.8); vertex(ax*width, ay*hy + bs*.20);
  endShape(CLOSE);
}
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
drawingContext.globalAlpha = 1;
